INSERT INTO lesson_units (id, unit_no, title, source_path, summary, grammar_focus, level, raw_content) VALUES (72, 72, 'some  and any  ➜', 'lecture/unit_072_some__and_any__➜', 'the 2–4 ➜ Units 74–76 Names with and without  the ➜ Units 77–78Athe 1 We use the when there is only one of something:', 'going to', 'A2', '# บทเรียน: some  and any  ➜

